  color: var(--c-text-main) !important;
  border: none !important;
}

/* 对方气泡小尾巴 (颜色自动同步所在气泡背景) */
.bubble-them-custom::after {
  content: "" !important;
  position: absolute !important;
  left: -3px !important;
  bottom: 28% !important;
  width: 6px !important;
  height: 6px !important;
  background-color: inherit !important;
  border-radius: 0 0 0 2px !important;
  transform: rotate(45deg) !important;
  z-index: 1 !important;
}

/* ── 我方气泡：指定微灰冷白 (#F7F8FA) + 清透中性质感细轮廓 (彻底无阴影) ── */
.bubble-me-custom {
  background: var(--c-me-bg) !important;
  color: var(--c-text-main) !important;
  border: 1px solid var(--c-me-border) !important;
  box-shadow: none !important;
  z-index: 2 !important;
}

/* 我方气泡小尾巴底色 */
.bubble-me-custom::after {
  content: "" !important;
  position: absolute !important;
  right: -3px !important;
  bottom: 28% !important;
  width: 6px !important;
  height: 6px !important;
  background-color: var(--c-me-bg) !important;
  border-radius: 0 1px 0 0 !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
}

/* 我方气泡小尾巴细描边 */
.bubble-me-custom::before {
  content: "" !important;
  position: absolute !important;
  right: -3.5px !important;
  bottom: 28% !important;
  width: 5.5px !important;
  height: 5.5px !important;
  background-color: transparent !important;
  border-right: 1px solid var(--c-me-border) !important;
  border-top: 1px solid var(--c-me-border) !important;
  border-radius: 0 1px 0 0 !important;
  transform: rotate(45deg) !important;
  z-index: 1 !important;
}

/* ── 表情包、图片与全类型卡片深度脱壳 ── */
.msg-bubble-wrapper .bubble-me-custom.no-padding,
.msg-bubble-wrapper .bubble-them-custom.no-padding,
