  transform: none !important;
  min-height: auto !important;
  min-width: 0 !important;
}

/* 消除脱壳气泡的尾巴 */
.msg-bubble-wrapper:has(img[alt="sticker"]) .bubble-me-custom::before,
.msg-bubble-wrapper:has(img[alt="sticker"]) .bubble-me-custom::after,
.msg-bubble-wrapper:has(img[alt="sticker"]) .bubble-them-custom::before,
.msg-bubble-wrapper:has(img[alt="sticker"]) .bubble-them-custom::after,
.msg-bubble-wrapper:has(.msg-image-wrapper) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-image-wrapper) .bubble-me-custom::after,
.msg-bubble-wrapper:has(.msg-image-wrapper) .bubble-them-custom::before,
.msg-bubble-wrapper:has(.msg-image-wrapper) .bubble-them-custom::after,
.msg-bubble-wrapper:has(.msg-image-card) .bubble-me-custom::before,
.msg-bubble-wrapper:has(.msg-image-card) .bubble-me-custom::after,
.msg-bubble-wrapper:has(.msg-image-card) .bubble-them-custom::before,
.msg-bubble-wrapper:has(.msg-image-card) .bubble-them-custom::after,
.msg-bubble-wrapper:has([class*="card"]) .bubble-me-custom::before,
.msg-bubble-wrapper:has([class*="card"]) .bubble-me-custom::after,
.msg-bubble-wrapper:has([class*="card"]) .bubble-them-custom::before,
.msg-bubble-wrapper:has([class*="card"]) .bubble-them-custom::after,
.msg-bubble-wrapper:has([class*="invite"]) .bubble-me-custom::before,
